INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히메지 시립미술관', '姫路市立美術館', 'MUSEUM', '兵庫県', '姫路市', 34.842800, 134.697400, 'FIXED', '10:00', '17:00', 'MON', '입장 16:30까지. 월요일(공휴일이면 다음 평일)·연말연시 휴관', '상설전 210엔 (고교·대학생 150엔, 초중학생 100엔. 기획전 별도)', '옛 육군 무기고·피복고였던 메이지 시대 붉은 벽돌 건물을 쓰는 미술관. 국가 등록유형문화재이고, 모네·피사로·마티스 등 프랑스 미술 컬렉션실이 있다.', '히메지성을 배경으로 한 벽돌 건물과 조각 정원이 사진 명소다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('효고 현립역사박물관', '兵庫県立歴史博物館', 'MUSEUM', '兵庫県', '姫路市', 34.843800, 134.697700, 'FIXED', '10:00', '17:00', 'MON', '입관 16:30까지. 월요일(공휴일이면 다음 날)·연말연시 휴관', '200엔 (대학생 150엔, 고교생 이하 무료. 특별전 별도)', '히메지성 터 안에 있는 박물관으로 효고의 역사와 성·축제·어린이 문화를 다룬다.', '1층은 무료 공간이다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('지치부 마쓰리 회관', '秩父まつり会館', 'MUSEUM', '埼玉県', '秩父市', 35.997700, 139.083500, 'FIXED', '09:00', '17:00', NULL, '4~11월 기준, 12~3월은 10:00부터. 입관 16:30까지. 3~11월 넷째·다섯째 화요일, 12~2월 매주 화요일 휴관(공휴일은 개관). 12/29~1/1 휴관', '500엔 (초중학생 250엔)', '유네스코 무형문화유산 "지치부 요마쓰리"를 소개하는 전시관. 실물 크기 가사보코와 야타이를 상설 전시한다.', '프로젝션 매핑으로 축제 밤의 열기를 보여 주고, 지치부역에서 걸어서 3분이다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('지치부 메이센관', 'ちちぶ銘仙館', 'MUSEUM', '埼玉県', '秩父市', 35.993000, 139.088700, 'FIXED', '09:00', '16:00', NULL, '체험 접수 9:00~11:30, 13:00~15:00. 연말연시 휴관', '210엔 (초중학생 100엔)', '1930년에 지은 옛 섬유공업시험장 건물(국가 등록유형문화재)을 쓰는 지치부 메이센 자료관.', '베틀 짜기·염색 체험을 할 수 있다(별도 요금).', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('지치부 후루사토관', 'ちちぶ巡礼と民話のやかた 秩父ふるさと館', 'HISTORIC', '埼玉県', '秩父市', 35.996600, 139.084900, 'FIXED', '09:00', '17:00', NULL, '4~11월 기준, 12~3월은 10:00부터. 입관 16:30까지. 넷째·다섯째 화요일(공휴일은 개관), 12/29~1/1 휴관', '400엔 (초중학생 200엔. 마쓰리 회관 공통권 600엔)', '다이쇼~쇼와 초기의 메이센 도매상 점포와 흙벽 창고(국가 등록유형문화재)를 살린 시설. 지치부 순례와 민화를 소개한다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('가마도 신사', '宝満宮竈門神社', 'SHRINE_TEMPLE', '福岡県', '太宰府市', 33.535600, 130.551900, 'ALWAYS', NULL, NULL, NULL, '참배 상시. 수여소 8:30~18:00', '무료', '연애·인연의 신 다마요리히메를 모신 신사. 경내에서 다자이후 시내가 내려다보인다.', '가타야마 마사미치가 디자인한 수여소 건물이 볼거리다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('다자이후 정청 터', '大宰府政庁跡', 'HISTORIC', '福岡県', '太宰府市', 33.514800, 130.515700, 'ALWAYS', NULL, NULL, NULL, '견학 자유', '무료', '7세기 후반부터 헤이안 시대까지 규슈 전체를 다스린 고대 최대 지방 관청 "다자이후"의 중심지. 넓은 잔디에 초석이 남은 국가 특별사적이다.', '봄엔 주변 약 100그루 벚꽃이 피고, 앱으로 CG 복원 정청을 볼 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('다자이후 전시관', '大宰府展示館', 'MUSEUM', '福岡県', '太宰府市', 33.514200, 130.516800, 'FIXED', '09:00', '16:30', 'MON', '월요일(공휴일이면 다음 날)·12/28~1/4 휴관', NULL, '다자이후 정청 터 발굴 유구 일부를 보존 공개하고, 출토품과 복원 모형으로 다자이후의 역사를 소개한다.', '연호 "레이와"의 유래가 된 730년 매화 연회 이야기를 전시한다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('구조하치만 옛 청사 기념관', '郡上八幡旧庁舎記念館', 'HISTORIC', '岐阜県', '郡上市', 35.749200, 136.962000, 'FIXED', '08:30', '17:00', NULL, '12/29~1/3 휴관', '무료', '1936년에 지은 옛 하치만 정 사무소 건물(국가 등록문화재). 지금은 관광안내소·휴게소로 쓰이고, 구조 오도리 체험과 식사도 할 수 있다.', '구조하치만 산책을 시작할 때 들르기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('야나카 물의 골목', 'やなか水のこみち', 'HISTORIC', '岐阜県', '郡上市', 35.750900, 136.962600, 'ALWAYS', NULL, NULL, NULL, '상시 산책 가능', '무료', '나가라강과 요시다강의 둥근 돌 약 8만 개를 깔아 물의 흐름을 표현한 돌길. 수로·버드나무·옛 상가와 어우러진다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('아카렌가 향토관', '秋田市立赤れんが郷土館', 'HISTORIC', '秋田県', '秋田市', 39.719400, 140.116700, 'FIXED', '09:30', '16:30', NULL, '연말연시(12/29~1/3)·전시 교체 기간 휴관', '310엔 (고교생 이하 무료)', '1912년에 완공한 옛 아키타은행 본점 양식 건물로 국가 중요문화재. 판화가 가쓰히라 도쿠시 기념관이 함께 있다.', '네부리나가시관과 공통권(370엔)이 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('센슈 미술관', '秋田市立千秋美術館', 'MUSEUM', '秋田県', '秋田市', 39.717300, 140.125700, 'FIXED', '10:00', '18:00', NULL, '입관 17:30까지. 12/29~1/3·건물 점검일 휴관', '상설전 310엔 (대학생 210엔, 고교생 이하 무료)', '아키타 난가와 아키타 출신 작가 작품, 서양화가 오카다 겐조 기념관이 있는 시립 미술관.', 'JR 아키타역 서쪽 출구에서 걸어서 5분이다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('모가미 요시아키 역사관', '最上義光歴史館', 'MUSEUM', '山形県', '山形市', 38.252500, 140.330900, 'FIXED', '09:00', '17:00', 'MON', '입관 16:30까지. 월요일(공휴일이면 다음 평일) 휴관', '무료', '야마가타 번영의 기초를 닦은 전국 무장 모가미 요시아키와 야마가타의 역사를 소개하는 시설. 요시아키의 투구와 쇠 지휘봉을 전시한다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('야마가타 시 향토관 (옛 사이세이칸)', '山形市郷土館', 'HISTORIC', '山形県', '山形市', 38.253500, 140.325800, 'FIXED', '09:00', '16:30', NULL, '가조 공원 안. 휴관일은 공식 확인', '무료', '1878년 병원으로 지은 "사이세이칸"을 옮겨 복원한 건물(국가 중요문화재). 의학 자료와 향토 자료를 전시한다.', '가조 공원 산책과 묶어 돌기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('요코테 시 마스다 만화미술관', '横手市増田まんが美術館', 'MUSEUM', '秋田県', '横手市', 39.206500, 140.553200, 'FIXED', '10:00', '18:00', NULL, '입관 17:30까지. 셋째 화요일(공휴일이면 다음 날) 휴관', '무료 (특별기획전은 유료)', '원화 40만 장 넘게 소장한 만화 전문 미술관. 원화 전시와 보존에 힘을 쏟는다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('고산넨 전투 가나자와 자료관', '後三年合戦金沢資料館', 'MUSEUM', '秋田県', '横手市', 39.384400, 140.545300, 'FIXED', '09:00', '17:00', 'MON', '입관 16:30까지. 월요일(공휴일이면 다음 날) 휴관', '100엔 (요코테 4관 공통, 고교·대학생 50엔, 중학생 이하 무료)', '헤이안 시대 "고산넨 전투"의 무대로 추정되는 가나자와 성터 근처의 자료관.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('간푸잔 회전 전망대', '寒風山回転展望台', 'VIEWPOINT', '秋田県', '男鹿市', 39.931200, 139.876300, 'VARIES', NULL, NULL, NULL, '전망대는 3월 중순~12월 상순 8:30~17:00 (날짜는 공식 확인)', '550엔 (고교생 이하 270엔)', '잔디로 덮인 표고 355m 간푸잔의 꼭대기 전망대. 4층이 약 13분에 한 바퀴 도는 회전 전망대다.', '맑으면 멀리 조카이산까지 보인다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('미우라 아야코 기념문학관', '三浦綾子記念文学館', 'MUSEUM', '北海道', '旭川市', 43.751600, 142.366600, 'FIXED', '09:00', '17:00', 'MON', '입관 16:30까지. 월요일(공휴일이면 다음 날) 휴관, 7·8월은 무휴. 12/28~1/5 휴관', '700엔 (대학생 300엔, 고교생 이하 무료)', '아사히카와 출신 작가 미우라 아야코의 문학관. 소설 『빙점』의 무대인 견본림 안에 있다.', '견본림 산책 뒤 찻집에서 쉬어 가기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('이노우에 야스시 기념관', '井上靖記念館', 'MUSEUM', '北海道', '旭川市', 43.796900, 142.367400, 'FIXED', '09:00', '17:00', NULL, '입관 16:30까지. 휴관일은 공식 확인', '300엔 (고교생 150엔, 중학생 이하 무료)', '작가 이노우에 야스시가 태어난 아사히카와의 문학관. 자필 노트와 원고, 도쿄 서재를 옮겨 재현한 공간이 있다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('아사히카와 시 과학관 사이파루', '旭川市科学館', 'MUSEUM', '北海道', '旭川市', 43.756700, 142.367100, 'FIXED', '09:30', '17:00', 'MON', '입관 16:30까지. 월요일(공휴일이면 다음 날)·월말 평일 휴관, 여름(7/21~8/31)은 무휴. 연말연시 휴관', '상설전 410엔 (고교생 280엔, 중학생 이하 무료. 플라네타리움 별도)', '"신기함에서 시작하는 과학과의 만남"을 주제로 한 체험형 과학관. 칼 자이스 투영기를 쓰는 플라네타리움과 천문대가 있다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오타루 시립 종합박물관 운하관', '小樽市総合博物館 運河館', 'MUSEUM', '北海道', '小樽市', 43.199900, 141.000300, 'FIXED', '09:30', '17:00', NULL, '12/29~1/3 휴관', '300엔 (고교생 150엔, 중학생 이하 무료)', '오타루 운하 옆 옛 창고 건물을 살린 시설. 항구 도시 오타루의 성립과 생활의 변천을 소개한다.', '운하 산책과 묶어 돌기 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오타루 예술촌', '小樽芸術村', 'MUSEUM', '北海道', '小樽市', 43.196800, 140.999600, 'FIXED', '09:30', '17:00', NULL, '5~10월 기준(매월 넷째 수요일 휴관), 11~4월 10:00~17:00·매주 수요일 휴관(공휴일이면 다음 날). 입장 30분 전 마감, 연말연시 휴관', '관마다 다름 (5관 공통권 3,500엔)', '옛 은행·창고 같은 역사적 건물을 활용한 미술관 단지. 스테인드글라스 미술관, 니토리 미술관, 서양미술관, 우키요에 미술관 등이 있다.', NULL, NULL, NULL, DATE '2026-11-22', NULL);
